        long long total = -1;
        for (int s = 0; s < 1024; s++) total = (total + dp[s]) % MOD;
        long long half = 1, base = 2;
        for (long long e = cnt[1]; e > 0; e >>= 1) {
            if (e & 1) half = half * base % MOD;
            base = base * base % MOD;
        }
        return (int)(total * half % MOD);
    }
};

